                'tool-call': '<details class="tool-call" data-status="done" open><summary class="tool-call-summary"><span class="tool-call-name">search_web</span> <span class="tool-call-status" data-status="done">Done</span></summary><div class="tool-call-content"><div class="tool-call-input" role="group" aria-label="Input"><pre tabindex="0">{"query": "weather in London"}</pre></div><div class="tool-call-output" role="group" aria-label="Output"><pre tabindex="0">12 degrees, light rain</pre></div></div></details>',
