                "net-promoter-score-picker": {"usage":{"lang":"html","code":"<p>How likely are you to recommend us to a friend or colleague?</p>\n<NetPromoterScorePicker\n  label=\"How likely are you to recommend us?\"\n  value=\"{score}\"\n>\n  <NetPromoterScorePickerButton\n    value=\"0\"\n    label=\"0 - Not at all likely\"\n    onclick=\"{handleClick}\"\n  />\n  <NetPromoterScorePickerButton\n    value=\"1\"\n    label=\"1\"\n    onclick=\"{handleClick}\"\n  />\n  <NetPromoterScorePickerButton\n    value=\"2\"\n    label=\"2\"\n    onclick=\"{handleClick}\"\n  />\n  <NetPromoterScorePickerButton\n    value=\"3\"\n    label=\"3\"\n    onclick=\"{handleClick}\"\n  />\n  <NetPromoterScorePickerButton\n    value=\"4\"\n    label=\"4\"\n    onclick=\"{handleClick}\"\n  />\n  <NetPromoterScorePickerButton\n    value=\"5\"\n    label=\"5\"\n    onclick=\"{handleClick}\"\n  />\n  <NetPromoterScorePickerButton\n    value=\"6\"\n    label=\"6\"\n    onclick=\"{handleClick}\"\n  />\n  <NetPromoterScorePickerButton\n    value=\"7\"\n    label=\"7\"\n    onclick=\"{handleClick}\"\n  />\n  <NetPromoterScorePickerButton\n    value=\"8\"\n    label=\"8\"\n    onclick=\"{handleClick}\"\n  />\n  <NetPromoterScorePickerButton\n    value=\"9\"\n    label=\"9\"\n    onclick=\"{handleClick}\"\n  />\n  <NetPromoterScorePickerButton\n    value=\"10\"\n    label=\"10 - Extremely likely\"\n    onclick=\"{handleClick}\"\n  />\n</NetPromoterScorePicker>\n<p>Selected score: {score}</p>\n"}},
